// The collector: Cheney's, over Fixpt's objects. Each root copied, then
// the copies scanned, header by header (a word no header begins a pair);
// a moved object's forwarding, tag 111, its copy's index, in a pair's first
// word and in the word below a bloblet's suffix.

// The collector: tier 1's (C332), Coopt's baseline, given the engine's
// roots (`roots`, the globals, the constants, the names' symbols and
// keywords) between its start and its end, each forwarded in place; then
// room for what the step needs, as `heap-room` counts it, the limit
// raised if need be (`room!`).
pub fn roots_forwarded_x(mut rs: FlatArray<i64>, mut i: i64, mut n: i64) -> () {
    loop {
        if i64_gt_eq(i, n) {
            return ();
        } else {
            flatarray_set_i64_x(rs, i, forward_x(flatarray_ref_i64(rs, i)));
            i = i64_plus(i, 1i64);
            continue;
        }
    }
}

pub fn collect_x(roots: FlatArray<i64>, globals: FlatArray<i64>, consts: FlatArray<i64>, need: i64) -> () {
    collect_begin_x();
    roots_forwarded_x(roots, 0i64, flatarray_length_i64(roots));
    roots_forwarded_x(globals, 0i64, flatarray_length_i64(globals));
    roots_forwarded_x(consts, 0i64, flatarray_length_i64(consts));
    roots_forwarded_x(get(symbol_objects()), 0i64, flatarray_length_i64(get(symbol_objects())));
    roots_forwarded_x(get(keyword_objects()), 0i64, flatarray_length_i64(get(keyword_objects())));
    set(sched_state(), forward_x(get(sched_state())));
    collect_end_x();
    room_x(i64_plus(need, i64_quotient(need, 2i64)))
}

